#include <stdio.h>

int main() {
    int n = 360;
    printf("Prime factors of %d:", n);
    for (int p = 2; p * p <= n; p++) {
        while (n % p == 0) {
            printf(" %d", p);
            n /= p;
        }
    }
    if (n > 1) {
        printf(" %d", n);
    }
    printf("\n");
    return 0;
}
